insert into public.products(slug,category,brand,collection,name,material,style,color,price,description,features,image_path,sort_order,is_available) select 'korfad-ex-asati','interior','KORFAD','EXELLENCE','KORFAD ASATI','Фарбоване покриття','Сучасний','Заводські кольори RAL','Ціна за запитом','KORFAD ASATI — фарбовані міжкімнатні двері колекції EXELLENCE. Доступні підтверджені кольори RAL і виконання OUTSIDE або INSIDE; точну комплектацію й ціну уточнюйте у менеджера.',jsonb_build_array('Фабрика KORFAD','Колекція EXELLENCE'),min(i),99999,false from k on conflict(slug) do update set name=excluded.name,description=excluded.description,image_path=excluded.image_path;
insert into public.product_options(product_slug,option_group,group_label,label,sort_order) select 'korfad-ex-asati','color','Колір',c,min(n) from k group by c on conflict(product_slug,option_group,label) do update set sort_order=excluded.sort_order,is_active=true;
insert into public.product_options(product_slug,option_group,group_label,label,sort_order) values('korfad-ex-asati','configuration','Відкривання','OUTSIDE',10),('korfad-ex-asati','configuration','Відкривання','INSIDE',20) on conflict(product_slug,option_group,label) do update set sort_order=excluded.sort_order,is_active=true;
insert into public.product_variants(product_slug,selections,image_path,sort_order,is_active) select 'korfad-ex-asati',jsonb_build_object('color',c,'configuration',o),i,n,true from k on conflict(product_slug,selections) do update set image_path=excluded.image_path,sort_order=excluded.sort_order,is_active=true;
insert into public.product_media(product_slug,kind,label,image_path,sort_order) select 'korfad-ex-asati','gallery','Колір: '||c||' · '||o,i,n from k source where not exists(select 1 from public.product_media m where m.product_slug='korfad-ex-asati' and m.kind='gallery' and m.image_path=source.i);
